mapper.select:
SELECT id, food_option_id, food_name_snapshot, category_snapshot, tags_snapshot_json, actual_price,
       meal_type, eaten_at, business_date, source, created_at, updated_at
FROM diet_records
WHERE user_id = #{userId} AND deleted_at IS NULL
  AND business_date BETWEEN #{startDate} AND #{endDate}
AND meal_type = #{mealType}
AND LOWER(TRIM(category_snapshot)) LIKE CONCAT('%', #{category}, '%') ESCAPE '\\'
AND source = #{source}
ORDER BY eaten_at DESC, id DESC
